<?php
require_once __DIR__.'/../includes/functions.php';require_admin();
$stats=[
 'customers'=>(int)db()->query("SELECT COUNT(*) FROM users WHERE role='customer'")->fetchColumn(),
 'products'=>(int)db()->query('SELECT COUNT(*) FROM products WHERE is_active=1')->fetchColumn(),
 'orders'=>(int)db()->query('SELECT COUNT(*) FROM orders')->fetchColumn(),
 'revenue'=>(float)db()->query("SELECT COALESCE(SUM(total),0) FROM orders WHERE payment_status='paid'")->fetchColumn(),
 'pending'=>(int)db()->query("SELECT COUNT(*) FROM orders WHERE status='pending'")->fetchColumn(),
 'requests'=>(int)db()->query("SELECT COUNT(*) FROM service_requests WHERE status IN ('new','quoted')")->fetchColumn(),
 'consultations'=>(int)db()->query("SELECT COUNT(*) FROM consultations WHERE status IN ('pending','approved') AND preferred_date>=CURDATE()")->fetchColumn(),
];
$months=db()->query("SELECT DATE_FORMAT(created_at,'%Y-%m') AS month, SUM(CASE WHEN payment_status='paid' THEN total ELSE 0 END) AS revenue FROM orders WHERE created_at>=DATE_SUB(CURDATE(),INTERVAL 5 MONTH) GROUP BY DATE_FORMAT(created_at,'%Y-%m') ORDER BY month")->fetchAll();
$top=db()->query("SELECT oi.product_name,SUM(oi.quantity) AS quantity FROM order_items oi JOIN orders o ON o.id=oi.order_id WHERE o.status<>'cancelled' GROUP BY oi.product_id,oi.product_name ORDER BY quantity DESC LIMIT 5")->fetchAll();
$latest=db()->query('SELECT order_number,customer_name,total,status,created_at FROM orders ORDER BY created_at DESC LIMIT 6')->fetchAll();
$revenueValues=array_map(fn($row)=>(float)$row['revenue'],$months);
$maxRevenue=$revenueValues?max(1.0,...$revenueValues):1.0;
$adminTitle='Overview · Yucca Fabrics';require __DIR__.'/../includes/admin-header.php';
?>
<div class="flex flex-wrap items-end justify-between gap-4"><div><p class="text-xs uppercase tracking-widest text-sage">A clear view of today</p><h1 class="mt-2 font-serif text-4xl">Overview</h1></div><a class="rounded-full bg-forest px-5 py-2.5 text-sm text-white" href="<?= e(url('shop.php')) ?>">View storefront ↗</a></div>
<div class="mt-8 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><?php foreach([['Customers',$stats['customers'],'Registered accounts'],['Products',$stats['products'],'Active in the catalogue'],['Orders',$stats['orders'],$stats['pending'].' pending'],['Paid revenue',money($stats['revenue']),'Confirmed paid orders'],['Service requests',$stats['requests'],'Awaiting attention'],['Consultations',$stats['consultations'],'Upcoming or pending']] as [$label,$value,$hint]): ?><article class="bg-white p-5"><p class="text-xs uppercase tracking-widest text-gray-500"><?= e($label) ?></p><p class="mt-3 font-serif text-3xl"><?= e((string)$value) ?></p><p class="mt-2 text-xs text-gray-500"><?= e($hint) ?></p></article><?php endforeach; ?></div>
<div class="mt-8 grid gap-6 xl:grid-cols-[1.4fr_1fr]"><section class="bg-white p-6"><h2 class="font-serif text-2xl">Paid revenue · recent months</h2><?php if(!$months): ?><p class="mt-8 text-sm text-gray-500">Sales will appear here when orders are placed and marked paid.</p><?php else: ?><div class="mt-8 flex h-56 items-end gap-3 border-b border-black/10"><?php foreach($months as $month): ?><div class="flex h-full flex-1 flex-col items-center justify-end gap-2"><span class="text-[10px]"><?= e(number_format((float)$month['revenue']/1000,1)) ?>k</span><div class="w-full rounded-t-sm bg-sage" style="height:<?= max(3,(int)(((float)$month['revenue']/$maxRevenue)*70)) ?>%"></div><span class="mb-2 text-[10px] text-gray-500"><?= e(date('M',strtotime($month['month'].'-01'))) ?></span></div><?php endforeach; ?></div><?php endif; ?></section><section class="bg-white p-6"><h2 class="font-serif text-2xl">Best-selling products</h2><?php if(!$top): ?><p class="mt-5 text-sm text-gray-500">Product sales appear after your first orders.</p><?php else: ?><div class="mt-4 divide-y divide-black/5"><?php foreach($top as $item): ?><div class="flex justify-between gap-4 py-3 text-sm"><span><?= e($item['product_name']) ?></span><span class="font-semibold"><?= (int)$item['quantity'] ?></span></div><?php endforeach; ?></div><?php endif; ?></section></div>
<section class="mt-8 bg-white p-6"><h2 class="font-serif text-2xl">Recent orders</h2><?php if($latest): ?><div class="mt-4 overflow-x-auto"><table class="w-full min-w-[600px] text-left text-sm"><thead class="text-xs uppercase text-gray-500"><tr><th class="py-3">Order</th><th>Customer</th><th>Total</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($latest as $order): ?><tr class="border-t border-black/5"><td class="py-3"><?= e($order['order_number']) ?></td><td><?= e($order['customer_name']) ?></td><td><?= e(money($order['total'])) ?></td><td class="capitalize"><?= e($order['status']) ?></td><td><?= e(date('M j',strtotime($order['created_at']))) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><p class="mt-4 text-sm text-gray-500">No orders yet.</p><?php endif; ?></section>
<?php require __DIR__.'/../includes/admin-footer.php'; ?>
